import {useEffect,useMemo,useRef,useState} from 'react';
import {useTranslation} from 'react-i18next';
import {MediaImage,saveLocalImage} from './media';
import {ArrowRight,ArrowUpRight,ArrowLeft,CalendarDays,Check,ChevronDown,Clock,Heart,Instagram,Menu,X,ShoppingBag,ShoppingCart,UserRound,Volume2,VolumeX,Sun,Moon,Scissors,GraduationCap,MapPin,Phone,Plus,Minus,Trash2,Settings,LayoutDashboard,Image,Tag,Music2,ShieldCheck,LogOut,Search,Star,MessageCircle,PenLine,Save,Users,Package,BookOpen,Lock,Eye,EyeOff} from 'lucide-react';
import{gallery,money,type Booking,type Service,type Master,type Product,type Content}from './data';
import{configured,supabase,readDemo,writeDemo,readLive,saveEntity,deleteEntity,createBooking,makeOrder,checkAdmin,type CatalogCategory,type State}from './store';
const routes=['Главная','Услуги','Мастера','Запись','Обучение','Магазин','Галерея','Отзывы','О нас','Контакты','Кабинет'];
const today=()=>new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Bishkek'});
const nextDays=()=>Array.from({length:14},(_,i)=>{const d=new Date();d.setDate(d.getDate()+i);return d.toLocaleDateString('en-CA',{timeZone:'Asia/Bishkek'})});
const times=Array.from({length:20},(_,i)=>{const m=9*60+i*30;return `${String(Math.floor(m/60)).padStart(2,'0')}:${String(m%60).padStart(2,'0')}`});
const uid=()=>crypto.randomUUID();
const safeText=(s:string)=>s.replace(/[<>]/g,'').slice(0,1200);
const IconButton=({icon:Icon,label,onClick,badge}:{icon:typeof Menu;label:string;onClick:()=>void;badge?:number})=><button aria-label={label} title={label} className="icon-button" onClick={onClick}><Icon size={19} strokeWidth={1.8}/>{badge? <span className="count">{badge}</span>:null}</button>;
const Section=({eyebrow,title,children,action}:{eyebrow:string;title:string;children:React.ReactNode;action?:React.ReactNode})=>{const {t}=useTranslation();return <section className="section shell"><div className="section-heading"><div><div className="eyebrow">{t(eyebrow)}</div><h2>{t(title)}</h2></div>{action}</div>{children}</section>};
const BackgroundDecor=()=> <div className="bg-petals" aria-hidden="true"><span className="petal petal-1"/><span className="petal petal-2"/><span className="petal petal-3"/><span className="petal petal-4"/><span className="petal petal-5"/><span className="petal petal-6"/><span className="petal petal-7"/></div>;
 const ImageUpload=({value,onChange,label,uploadImage,uploading,library=[]}:{value:string;onChange:(v:string)=>void;label:string;uploadImage:(file:File,onSaved:(url:string)=>void)=>Promise<void>;uploading:boolean;library?:string[]})=>{const {t}=useTranslation();return <div className="admin-image-picker"><label className="field">{label}  {t("— ссылка")}<input value={value||''} onChange={e=>onChange(e.target.value)} placeholder="https://..."/></label><label className="field">{t("Или загрузить фото с устройства")}<input type="file" accept="image/jpeg,image/png,image/webp,image/gif,image/avif" disabled={uploading} onChange={e=>{const f=e.target.files?.[0];if(f)void uploadImage(f,onChange);e.target.value=''}}/></label>{library.length>0&&<label className="field">Или выбрать из галереи<select value="" onChange={e=>{if(e.target.value)onChange(e.target.value)}}><option value="">Выберите фотографию</option>{library.map((image,i)=><option value={image} key={i}>Фотография {i+1}</option>)}</select></label>}{value&&<div className="admin-preview"><MediaImage src={value} alt="Предпросмотр изображения"/><span>{t("Так фотография будет кадрироваться в карточке")}</span></div>}</div>;};
export default function App(){
 const {t,i18n}=useTranslation();
 const locale=i18n.resolvedLanguage?.startsWith('ky')?'ky':i18n.resolvedLanguage?.startsWith('en')?'en':'ru';
 const translateField=(obj:{localized?:{ky?:Record<string,string>;en?:Record<string,string>}}|null|undefined,field:string,fallback:string)=>{
   if(locale==='ru')return fallback;
   const translated=obj?.localized?.[locale]?.[field]?.trim();
   return translated||t(fallback,{defaultValue:fallback});
 };
 const siteText=(field:keyof Content)=>translateField(state.content,field,String(state.content[field]||''));
 const itemText=(obj:{localized?:{ky?:Record<string,string>;en?:Record<string,string>}}|null|undefined,field:string,value:string)=>translateField(obj,field,value);
 const [editLocale,setEditLocale]=useState<'ru'|'ky'|'en'>('ru');

 const[state,setState]=useState<State>(()=>readDemo());const[page,setPage]=useState('Главная');const[menu,setMenu]=useState(false);const[dark,setDark]=useState(false);const lang=i18n.language.toUpperCase();const[cart,setCart]=useState<Record<string,number>>({});const[fav,setFav]=useState<string[]>([]);const[admin,setAdmin]=useState(false);const[adminPage,setAdminPage]=useState('Обзор');const[adminAuth,setAdminAuth]=useState(false);const[authOpen,setAuthOpen]=useState(false);const[authMode,setAuthMode]=useState<'login'|'signup'>('login');const[authEmail,setAuthEmail]=useState('');const[authPass,setAuthPass]=useState('');const[authError,setAuthError]=useState('');const[notification,setNotification]=useState('');const[connectedError,setConnectedError]=useState('');const[loading,setLoading]=useState(configured);const[audioOn,setAudioOn]=useState(false);const audio=useRef<HTMLAudioElement>(null);
 const [authUser,setAuthUser]=useState<{id:string;email?:string}|null>(null);
 const [myBookings,setMyBookings]=useState<Booking[]>([]);
 const [myOrders,setMyOrders]=useState<State['orders']>([]);
 const[bookingServices,setBookingServices]=useState<string[]>([]);const[bookingMaster,setBookingMaster]=useState('any');const[bookingDate,setBookingDate]=useState(today());const[bookingTime,setBookingTime]=useState('');const[customer,setCustomer]=useState({name:'',phone:'',note:''});const[consent,setConsent]=useState(false);const[submitted,setSubmitted]=useState<Booking|null>(null);const[serviceCat,setServiceCat]=useState('Все');const[query,setQuery]=useState('');const[productCat,setProductCat]=useState('Все');const[contactOpen,setContactOpen]=useState(false);const[detail,setDetail]=useState<{type:'service'|'product'|'master';id:string}|null>(null);
 useEffect(()=>{if(configured)readLive().then(s=>setState(s)).catch(e=>setConnectedError(String(e))).finally(()=>setLoading(false))},[]);
 useEffect(()=>{if(!supabase)return;void supabase.auth.getUser().then(({data})=>setAuthUser(data.user?{id:data.user.id,email:data.user.email}:null));const {data:{subscription}}=supabase.auth.onAuthStateChange((_event,session)=>setAuthUser(session?.user?{id:session.user.id,email:session.user.email}:null));return()=>subscription.unsubscribe()},[]);
 useEffect(()=>{if(!supabase||!authUser){setMyBookings([]);setMyOrders([]);return;}let live=true;void Promise.all([supabase.from('bookings').select('*').eq('user_id',authUser.id).order('createdAt',{ascending:false}),supabase.from('orders').select('*').eq('user_id',authUser.id).order('date',{ascending:false})]).then(([b,o])=>{if(!live)return;if(!b.error)setMyBookings(b.data as Booking[]);if(!o.error)setMyOrders(o.data as State['orders'])});return()=>{live=false}},[authUser?.id,page,submitted?.id]);
 useEffect(()=>{if(!configured)writeDemo(state)},[state]);
 useEffect(()=>{if(!configured||!adminAuth)return;void readLive(true).then(setState).catch(e=>setConnectedError(String(e)))},[adminAuth]);
 useEffect(()=>{if(!supabase||!adminAuth)return;const channel=supabase.channel('elbem-admin-bookings').on('postgres_changes',{event:'*',schema:'public',table:'bookings'},async()=>{try{const {data,error}=await supabase!.from('bookings').select('*').order('createdAt',{ascending:false});if(!error&&data)setState(old=>({...old,bookings:data as Booking[]}))}catch{}}).subscribe();return()=>{void supabase!.removeChannel(channel)}},[adminAuth]);
 useEffect(()=>{document.documentElement.dataset.theme=dark?'dark':'light'},[dark]);
 const alert=(s:string)=>{setNotification(s);setTimeout(()=>setNotification(''),4500)};
 const go=(p:string)=>{setDetail(null);setPage(p);setMenu(false);setAdmin(false);window.scrollTo({top:0,behavior:'smooth'})};
 const change=<K extends keyof State>(key:K,val:State[K])=>setState(s=>({...s,[key]:val}));
 const activeServices=state.services.filter(s=>s.active!==false);
 const activeProducts=state.products.filter(p=>p.active!==false);
 const serviceCategories=['Все',...new Set(activeServices.map(x=>x.category))];
 const productCategories=['Все',...new Set(activeProducts.map(x=>x.category))];
 const activeMasters=state.masters.filter(m=>m.active!==false);
 const picked=bookingServices.map(id=>state.services.find(s=>s.id===id)).filter((x):x is Service=>Boolean(x));
 const total=picked.reduce((n,s)=>n+s.price,0);
 const duration=picked.reduce((n,s)=>n+s.duration,0);
 const possibleMasters=activeMasters.filter(m=>picked.every(s=>m.serviceIds.includes(s.id)));
 const [serverSlots,setServerSlots]=useState<string[]>([]);const [slotsLoading,setSlotsLoading]=useState(false);
 const occupied=state.bookings.filter(b=>b.date===bookingDate&&b.status!=='cancelled');
 const freeTimes=times.filter(t=>{const st=Number(t.slice(0,2))*60+Number(t.slice(3));if(st+Math.max(duration,30)>19*60)return false;if(state.blocked.includes(`${bookingDate}|${t}`)||state.blocked.includes(`${bookingMaster}|${bookingDate}|${t}`))return false;if(bookingDate===today()){const now=new Date();const n=now.getHours()*60+now.getMinutes();if(st<=n+30)return false}return !occupied.some(b=>{if(bookingMaster!=='any'&&b.masterId!==bookingMaster&&b.masterId!=='any')return false;const bst=Number(b.time.slice(0,2))*60+Number(b.time.slice(3));const bd=b.serviceIds.reduce((n,id)=>n+(state.services.find(s=>s.id===id)?.duration||30),0);return st<bst+bd&&st+duration>bst})});
 useEffect(()=>{if(!configured||!supabase||!bookingServices.length){setServerSlots([]);return;}let valid=true;setSlotsLoading(true);void Promise.resolve(supabase.rpc('available_slots',{p_date:bookingDate,p_service_ids:bookingServices,p_master:bookingMaster})).then(({data,error})=>{if(valid)setServerSlots(error?[]:(data||[]))}).finally(()=>{if(valid)setSlotsLoading(false)});return()=>{valid=false}},[bookingDate,bookingMaster,bookingServices.join(','),state.bookings.length,state.blocked.length]);
 const displayedTimes=configured?serverSlots:freeTimes;
 const wa=(msg:string)=>{const number=(state.content.whatsapp||import.meta.env.VITE_SALON_WHATSAPP||'').replace(/\D/g,'');if(!number){alert('Номер WhatsApp ещё не настроен. В деморежиме сообщение не отправляется.');return}window.open(`https://wa.me/${number}?text=${encodeURIComponent(msg)}`,'_blank','noopener,noreferrer')};
 const submitBooking=async()=>{if(!picked.length||!bookingTime||!displayedTimes.includes(bookingTime)||!customer.name.trim()||!/^\+?\d[\d\s()\-]{7,}$/.test(customer.phone)||!consent){alert('Выберите услуги, время, заполните имя и телефон и подтвердите согласие');return}const b:Booking={id:uid(),name:safeText(customer.name),phone:customer.phone,date:bookingDate,time:bookingTime,masterId:bookingMaster,serviceIds:bookingServices,total,status:'pending',note:safeText(customer.note),createdAt:new Date().toISOString()};try{if(configured){const id=await createBooking(b);if(id)b.id=String(id)}change('bookings',[b,...state.bookings]);setSubmitted(b);alert('Заявка создана. Ожидайте подтверждения администратора.')}catch(e){alert(`Не удалось сохранить запись: ${String(e)}`)}};
 const cartTotal=Object.entries(cart).reduce((sum,[id,n])=>sum+(state.products.find(p=>p.id===id)?.price||0)*n,0);
 const [orderName,setOrderName]=useState('');const[orderPhone,setOrderPhone]=useState('');
 const submitOrder=async(channel:'whatsapp'|'telegram'='whatsapp')=>{if(!orderName.trim()||!orderPhone.trim()||!Object.keys(cart).some(id=>cart[id]>0)){alert('Заполните контактные данные и добавьте товары');return}
  const telegramLink=telegramOwnerLink();
  const whatsappNumber=(content.whatsapp||import.meta.env.VITE_SALON_WHATSAPP||'').replace(/\D/g,'');
  if(channel==='telegram'&&!telegramLink){alert('Telegram владельца не настроен.');return}
  const text=`EL BEM — заказ\nКлиент: ${orderName}\nТелефон: ${orderPhone}\nТовары: ${Object.entries(cart).filter(([,qty])=>qty>0).map(([id,qty])=>`${state.products.find(p=>p.id===id)?.name||id} × ${qty}`).join(', ')}\nСумма: ${money(cartTotal)}`;
  const link=channel==='telegram'?telegramLink:whatsappNumber?`https://wa.me/${whatsappNumber}?text=${encodeURIComponent(text)}`:null;
  // Open from user gesture, before awaiting Supabase, to avoid popup blocking.
  const chatWindow=link?window.open(link,'_blank','noopener,noreferrer'):null;
  const order={id:uid(),name:orderName,phone:orderPhone,items:Object.entries(cart).filter(([,qty])=>qty>0).map(([id,quantity])=>({id,quantity,price:state.products.find(p=>p.id===id)?.price||0})),total:cartTotal,date:new Date().toISOString()};
  try{if(configured)await makeOrder(order);change('orders',[order,...state.orders]);setCart({});
  if(channel==='telegram'){
    try{await navigator.clipboard.writeText(text);alert('Заказ сохранён. В Telegram вставьте текст и нажмите «Отправить».')}
    catch{alert('Заказ сохранён. В Telegram вручную сообщите детали заказа владельцу.')} 
  }else if(whatsappNumber){alert('Заказ сохранён. Подтвердите отправку сообщения в открытом WhatsApp.')}
  else{alert('Заказ сохранён. Для отправки через WhatsApp владелец должен указать номер в Настройках.')}
  if(link&&!chatWindow)alert('Если чат не открылся, разрешите всплывающие окна.')
 }catch(e){if(chatWindow)chatWindow.close();alert('Заказ не сохранён: '+String(e))}};
 const login=async()=>{setAuthError('');if(!configured){if(admin){setAuthError('Для защищённого входа подключите Supabase. Демо-админка доступна через отдельный просмотр без настоящих данных.');return}alert('Демо-режим: регистрация недоступна без Supabase');return}try{const {error}=authMode==='signup'?await supabase!.auth.signUp({email:authEmail,password:authPass}):await supabase!.auth.signInWithPassword({email:authEmail,password:authPass});if(error)throw error;if(admin){const ok=await checkAdmin();if(!ok)throw Error('У аккаунта нет роли администратора');setAdminAuth(true)}setAuthOpen(false);alert(authMode==='signup'?'Проверьте email для подтверждения':'Вход выполнен')}catch(e){setAuthError(String(e))}};
 const openAdmin=()=>{setAdmin(true);setPage('Админка');setMenu(false);if(!configured)setAdminAuth(false);window.scrollTo(0,0)};
 const content=state.content;
 const mediaGallery=content.galleryImages??gallery;
 const openDetail=(type:'service'|'product'|'master',id:string)=>{setDetail({type,id});setPage('Подробнее');setMenu(false);window.scrollTo({top:0,behavior:'smooth'})};
 const AdminNav=['Обзор','Записи','Расписание','Услуги','Мастера','Товары','Категории','Контент сайта','Отзывы','Настройки'];
 const Header=()=> <><div className="topbar">{t("EL BEM · BEAUTY STUDIO · УЗГЕН")} <span>{t("ДЕМОНСТРАЦИОННАЯ ВЕРСИЯ")}</span></div><header className="header"><div className="shell header-inner"><button className="logo" onClick={()=>go('Главная')} aria-label="EL BEM — главная"><span className="logo-symbol">✦</span><span className="logo-word">EL <i>BEM</i><small>BEAUTY STUDIO</small></span></button><nav className="desktop-nav" aria-label="Главное меню">{['Главная','Услуги','Мастера','Запись','Обучение','О нас'].map(p=><button className={page===p?'active':''} key={p} onClick={()=>go(p)}>{t(p)}</button>)}</nav><div className="header-actions"><button className="lang" onClick={()=>void i18n.changeLanguage(lang==='RU'?'ky':lang==='KY'||lang==='KG'?'en':'ru')} title="Переключить язык">{lang==='KY'?'KG':lang}<ChevronDown size={13}/></button><IconButton icon={dark?Sun:Moon} label="Переключить тему" onClick={()=>setDark(!dark)}/><span className="desktop-action"><IconButton icon={ShoppingBag} label="Магазин" onClick={()=>go('Магазин')}/></span><IconButton icon={ShoppingCart} label="Корзина" badge={Object.values(cart).reduce((x,y)=>x+y,0)} onClick={()=>go('Корзина')}/><IconButton icon={UserRound} label="Личный кабинет" onClick={()=>go('Кабинет')}/><button className="book-head" onClick={()=>go('Запись')}>{t('Записаться')} <ArrowUpRight size={16}/></button><IconButton icon={menu?X:Menu} label="Открыть меню" onClick={()=>setMenu(!menu)}/></div></div></header>{menu&&<div className="menu-overlay"><div className="shell menu-grid">{routes.map(p=><button key={p} onClick={()=>go(p)}><span>{t(p)}</span><ArrowUpRight size={17}/></button>)}<button onClick={openAdmin}><span>{t("Для администратора")}</span><ShieldCheck size={17}/></button></div></div>}</>;
 const Floating=()=> <div className="floating"><button className="contact-float" onClick={()=>setContactOpen(!contactOpen)}><MessageCircle size={20}/><span>{t('Связаться')}</span></button><button className="music-float" onClick={()=>{if(!content.musicEnabled||!content.musicUrl){alert('Музыка пока не настроена администратором');return}if(audioOn){audio.current?.pause();setAudioOn(false)}else{audio.current?.play().then(()=>setAudioOn(true)).catch(()=>alert('Браузер не разрешил воспроизведение'))}}} aria-label={audioOn?'Выключить музыку':'Включить музыку'}>{audioOn?<Volume2 size={18}/>:<VolumeX size={18}/>}</button>{contactOpen&&<div className="contact-popup"><button className="close" onClick={()=>setContactOpen(false)}><X size={15}/></button><b>{t("Поможем с выбором")}</b><p>{t("Напишите менеджеру — ответим на вопросы об услугах и записи.")}</p><button className="btn btn-primary" onClick={()=>wa('Здравствуйте! У меня вопрос о салоне EL BEM.')}>{t("Написать в WhatsApp")} <ArrowUpRight size={15}/></button></div>}<audio ref={audio} src={content.musicUrl} loop preload="none"/></div>;

 const ServiceCards=({items}:{items:Service[]})=><div className="card-grid">{items.map(s=><article className="service-card" key={s.id}><button type="button" className="card-photo detail-photo-button" onClick={()=>openDetail('service',s.id)} aria-label={`Подробнее об услуге: ${itemText(s,'name',s.name)}`}><MediaImage src={s.image} alt={itemText(s,'name',s.name)} loading="lazy"/></button><div className="card-body"><div className="muted small">{itemText(s,'category',s.category)} · {s.duration}  {t("мин")}</div><button type="button" className="detail-title" onClick={()=>openDetail('service',s.id)}><h3>{itemText(s,'name',s.name)}</h3></button><div className="card-bottom"><strong>{t("от")} {money(s.price)}</strong><button aria-label={`Подробнее: ${itemText(s,'name',s.name)}`} onClick={()=>openDetail('service',s.id)}><ArrowUpRight size={19}/></button></div></div></article>)}</div>;
 const Home=()=> <><section className="hero"><div className="hero-flower flower-one">✽</div><div className="hero-flower flower-two">✳</div><div className="shell hero-grid"><div className="hero-text"><div className="eyebrow">{t("EL BEM · САЛОН КРАСОТЫ В УЗГЕНЕ")}</div><h1>{siteText('heroTitle')}<br/><em>{siteText('heroEmphasis')}</em></h1><p>{siteText('heroSubtitle')}</p><div className="hero-actions"><button className="btn btn-primary" onClick={()=>go('Запись')}>{t("Записаться онлайн")} <ArrowUpRight size={17}/></button><button className="text-link" onClick={()=>go('Услуги')}>{t("Наши услуги")} <ArrowRight size={17}/></button></div><div className="hero-note"><span className="note-star">✦</span>  {t("Ваше время для себя")}</div></div><div className="hero-portrait"><div className="hero-oval"/><MediaImage src={content.heroImage} alt="Beauty-портрет — демонстрационное изображение"/></div></div></section><div className="quick shell"><div className="quick-title">{t("Что вас интересует?")}</div><div className="quick-grid">{[['Услуги',Scissors],['Мастера',Users],['Запись',CalendarDays],['Обучение',GraduationCap],['Магазин',ShoppingBag],['Наши работы',Image]].map(([t,I])=><button key={String(t)} onClick={()=>go(t==='Наши работы'?'Галерея':String(t))}><I size={22}/><span>{i18n.t(String(t))}</span><ArrowUpRight size={14}/></button>)}</div></div><Section eyebrow="01 / УСЛУГИ" title="Ритуалы красоты" action={<button className="text-link" onClick={()=>go('Услуги')}>{t("Все услуги")} <ArrowUpRight size={17}/></button>}><p className="lead">{t("От выразительного образа до небольших деталей — выбирайте то, что подходит именно вам.")}</p><ServiceCards items={activeServices.slice(0,3)}/></Section><div className="feature-band"><div className="shell feature-grid"><div><div className="eyebrow">{t("02 / НАШ ПОДХОД")}</div><h2>{t("Красота — это")} <em>{t("ваша история.")}</em></h2><p>{t("Удобная запись, услуги в одном месте и внимание к индивидуальности. Мы сохранили только то, что действительно важно.")}</p><button className="btn btn-outline" onClick={()=>go('О нас')}>{t("О салоне")} <ArrowUpRight size={16}/></button></div><MediaImage src={gallery[1]} alt="Пример работы стилиста" loading="lazy"/></div></div><Section eyebrow="03 / СПЕЦИАЛИСТЫ" title="Найдите своего мастера" action={<button className="text-link" onClick={()=>go('Мастера')}>{t("Все мастера")} <ArrowUpRight size={16}/></button>}><div className="master-grid">{activeMasters.map(m=><article className="master-card" key={m.id}><MediaImage src={m.image} alt={itemText(m,'name',m.name)} loading="lazy"/><h3>{itemText(m,'name',m.name)}</h3><p>{itemText(m,'specialty',m.specialty)}</p><button className="text-link" onClick={()=>{setBookingMaster(m.id);go('Запись')}}>{t("Записаться")} <ArrowUpRight size={15}/></button></article>)}</div></Section><section className="offer"><div className="shell offer-inner"><div><span className="eyebrow">{t("СПЕЦИАЛЬНОЕ ПРЕДЛОЖЕНИЕ · DEMO")}</span><h2>{t("Время")} <em>{t("для себя")}</em></h2><p>{t("Лами + шугаринг. Условия и стоимость уточняйте у администратора салона.")}</p><button className="btn btn-light" onClick={()=>wa('Здравствуйте! Хочу узнать об акции «Лами + шугаринг».')}>{t("Уточнить акцию")} <ArrowUpRight size={17}/></button></div><div className="offer-mark">✳</div></div></section><Section eyebrow="04 / ПОРТФОЛИО" title="Красота в деталях" action={<button className="text-link" onClick={()=>go('Галерея')}>{t("Смотреть галерею")} <ArrowUpRight size={17}/></button>}><div className="gallery-row">{mediaGallery.slice(0,3).map((src,i)=><MediaImage src={src} alt={`Демонстрационное фото ${i+1}`} key={src} loading="lazy"/>)}</div></Section><Section eyebrow="05 / ОБУЧЕНИЕ" title={siteText('academyTitle')}><div className="academy-highlight"><MediaImage src={content.academyImage} alt="Обучение в beauty сфере" loading="lazy"/><div><p>{siteText('academyText')}</p><button className="btn btn-primary" onClick={()=>go('Обучение')}>{t("Узнать о курсах")} <ArrowUpRight size={16}/></button></div></div></Section><Section eyebrow="06 / КОНТАКТЫ" title="Всегда на связи"><div className="contact-cards"><div><MapPin size={24}/><h3>{siteText('address')||t("Узген, Кыргызстан")}</h3><p>{t("Уточните адрес и часы работы перед визитом.")}</p>{salonMapLink()&&<a className="text-link address-link" href={salonMapLink()!} target="_blank" rel="noopener noreferrer">{t("Открыть на карте")} <ArrowUpRight size={16}/></a>}</div><div><MessageCircle size={24}/><h3>{t("Есть вопросы?")}</h3><p>{t("Напишите менеджеру в WhatsApp — ответим о записи и услугах.")}</p><button className="text-link" onClick={()=>wa('Здравствуйте! Хочу уточнить информацию о салоне EL BEM.')}>{t("Связаться")} <ArrowUpRight size={16}/></button></div></div></Section></>;
 const ServicesPage=()=> <Section eyebrow="УСЛУГИ И ЦЕНЫ" title="Выберите ваш уход"><div className="filter-bar"><div className="chips">{serviceCategories.map(c=><button className={serviceCat===c?'selected':''} key={c} onClick={()=>setServiceCat(c)}>{c==='Все'?t(c):itemText(state.categories.find(x=>x.name===c),'name',c)}</button>)}</div><label className="search"><Search size={16}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Поиск услуги"/></label></div><ServiceCards items={activeServices.filter(s=>(serviceCat==='Все'||s.category===serviceCat)&&s.name.toLowerCase().includes(query.toLowerCase()))}/></Section>;
 const MastersPage=()=> <Section eyebrow="КОМАНДА" title="Наши мастера"><p className="lead">{t("Демонстрационные профили. Фотографии и имена заменяются владельцем через админ-панель.")}</p><div className="master-grid">{activeMasters.map(m=><article className="master-card large" key={m.id}><button type="button" className="master-photo-button" onClick={()=>openDetail('master',m.id)} aria-label={`Подробнее о мастере: ${itemText(m,'name',m.name)}`}><MediaImage src={m.image} alt={itemText(m,'name',m.name)}/></button><button type="button" className="detail-title" onClick={()=>openDetail('master',m.id)}><h3>{itemText(m,'name',m.name)}</h3></button><p>{itemText(m,'specialty',m.specialty)}</p><button className="btn btn-outline" onClick={()=>{setBookingMaster(m.id);go('Запись')}}>{t("Выбрать мастера")} <ArrowUpRight size={16}/></button></article>)}</div></Section>;
 const BookingPage=()=> <Section eyebrow="ОНЛАЙН-ЗАПИСЬ" title="Время для себя">{submitted?<div className="success-box"><Check size={35}/><h3>{t("Заявка создана")}</h3><p>{t("Номер:")} {submitted.id.slice(0,8)}{t(". Ожидайте подтверждения администратора. В деморежиме заявка сохраняется только в этом браузере.")}</p><button className="btn btn-primary" onClick={()=>wa(`Здравствуйте! Заявка EL BEM №${submitted.id.slice(0,8)}. ${submitted.name}, ${submitted.phone}. Услуги: ${submitted.serviceIds.map(id=>state.services.find(s=>s.id===id)?.name).join(', ')}. Дата: ${submitted.date}, время: ${submitted.time}.`)}>{t("Отправить в WhatsApp")} <ArrowUpRight size={17}/></button><button className="text-link" onClick={()=>{setSubmitted(null);setBookingServices([]);setBookingTime('')}}>{t("Новая запись")}</button></div>:<div className="booking-layout"><div className="booking-main"><div className="booking-step"><h3><span>01</span>  {t("Выберите услуги")}</h3><p>{t("Можно выбрать одну или несколько процедур.")}</p><div className="service-choices">{activeServices.map(s=><button className={bookingServices.includes(s.id)?'checked':''} key={s.id} onClick={()=>{setBookingServices(old=>old.includes(s.id)?old.filter(id=>id!==s.id):[...old,s.id]);setBookingTime('')}}><span className="choice-check">{bookingServices.includes(s.id)?<Check size={14}/>:<Plus size={14}/>}</span><span>{itemText(s,'name',s.name)}<small>{s.duration}  {t("мин")}</small></span><strong>{t("от")} {money(s.price)}</strong></button>)}</div></div><div className="booking-step"><h3><span>02</span>  {t("Выберите мастера")}</h3><p>{t("Выбор необязателен — мы можем подобрать специалиста.")}</p><div className="master-options"><button className={bookingMaster==='any'?'selected':''} onClick={()=>setBookingMaster('any')}>{t("Любой подходящий мастер")}</button>{possibleMasters.map(m=><button key={m.id} className={bookingMaster===m.id?'selected':''} onClick={()=>setBookingMaster(m.id)}>{itemText(m,'name',m.name)}</button>)}<button className={bookingMaster==='onsite'?'selected':''} onClick={()=>setBookingMaster('onsite')}>{t("Уточнить мастера на месте")}</button></div></div><div className="booking-step"><h3><span>03</span>  {t("Выберите день и время")}</h3><label className="field">{t("Дата")} <input type="date" min={today()} value={bookingDate} onChange={e=>{setBookingDate(e.target.value);setBookingTime('')}}/></label><div className="time-grid">{(bookingServices.length?displayedTimes:[]).map(t=><button key={t} className={bookingTime===t?'selected':''} onClick={()=>setBookingTime(t)}>{t}</button>)}</div>{!bookingServices.length?<p className="hint">{t("Сначала выберите услугу.")}</p>:!freeTimes.length?<p className="hint">{t("Для выбранной даты нет доступного времени.")}</p>:<p className="hint">{t("В деморежиме свободные часы приблизительные. Для настоящего салона требуется серверный календарь.")}</p>}</div><div className="booking-step"><h3><span>04</span>  {t("Контактные данные")}</h3><div className="two-fields"><label className="field">{t("Ваше имя")}<input value={customer.name} onChange={e=>setCustomer({...customer,name:e.target.value})} placeholder="Как к вам обращаться"/></label><label className="field">{t("Телефон")}<input value={customer.phone} onChange={e=>setCustomer({...customer,phone:e.target.value})} placeholder="+996 555 123 456"/></label></div><label className="field">{t("Комментарий")}<textarea rows={3} value={customer.note} onChange={e=>setCustomer({...customer,note:e.target.value})} placeholder="Если есть пожелания"/></label><label className="consent"><input type="checkbox" checked={consent} onChange={e=>setConsent(e.target.checked)}/>  {t("Согласен(на) на обработку предоставленных контактных данных для записи")}</label><button className="btn btn-primary" onClick={submitBooking}>{t("Отправить заявку")} <ArrowUpRight size={17}/></button></div></div><aside className="booking-summary"><div className="eyebrow">{t("ВАША ЗАПИСЬ")}</div><h3>{t("Красота в деталях")}</h3><div>{picked.length?picked.map(s=><div className="summary-row" key={s.id}><span>{itemText(s,'name',s.name)}</span><b>{money(s.price)}</b></div>):<p>{t("Услуги ещё не выбраны")}</p>}</div><div className="summary-row"><span>{t("Длительность")}</span><b>{duration}  {t("мин")}</b></div><div className="summary-row"><span>{t("Дата / время")}</span><b>{bookingDate} {bookingTime}</b></div><div className="summary-total"><span>{t("Ориентировочно")}</span><strong>{t("от")} {money(total)}</strong></div><small>{t("Стоимость может измениться после консультации.")}</small></aside></div>}</Section>;
 const ShopPage=()=> <Section eyebrow="BEAUTY SHOP" title="Красота в каждом дне">{!content.shopEnabled?<p>{t("Магазин временно недоступен.")}</p>:<><p className="lead">{t("Демонстрационный каталог для экзамена. Товары и цены не являются официальным ассортиментом салона.")}</p><div className="filter-bar"><div className="chips">{productCategories.map(c=><button className={productCat===c?'selected':''} key={c} onClick={()=>setProductCat(c)}>{c==='Все'?t(c):itemText(state.categories.find(x=>x.name===c),'name',c)}</button>)}</div></div><div className="card-grid">{activeProducts.filter(p=>productCat==='Все'||p.category===productCat).map(p=><article className="service-card" key={p.id}><button type="button" className="card-photo detail-photo-button" onClick={()=>openDetail('product',p.id)} aria-label={`Подробнее о товаре: ${itemText(p,'name',p.name)}`}><MediaImage src={p.image} alt={itemText(p,'name',p.name)} loading="lazy"/></button><div className="card-body"><div className="muted small">{itemText(p,'category',p.category)} · DEMO</div><button type="button" className="detail-title" onClick={()=>openDetail('product',p.id)}><h3>{itemText(p,'name',p.name)}</h3></button><div className="card-bottom"><strong>{money(p.price)}</strong><button onClick={()=>{setCart(v=>({...v,[p.id]:(v[p.id]||0)+1}));alert('Товар добавлен в корзину')}} aria-label={`В корзину: ${itemText(p,'name',p.name)}`}><ShoppingCart size={18}/></button></div></div></article>)}</div></>}</Section>;
 const AccountPage=()=> <Section eyebrow="ЛИЧНЫЙ КАБИНЕТ" title="Мой профиль">{!configured?<div className="account-panel"><p>Сейчас работает демонстрационный режим. Для личного кабинета нужен Supabase Auth.</p><button className="btn btn-outline" onClick={()=>go('Запись')}>Записаться без регистрации</button></div>:!authUser?<div className="account-panel"><p>Создайте аккаунт или войдите, чтобы просматривать собственные записи и заказы. Для записи регистрация не обязательна.</p><button className="btn btn-primary" onClick={()=>{setAuthMode('login');setAuthOpen(true)}}>Войти в кабинет</button><button className="btn btn-outline" onClick={()=>{setAuthMode('signup');setAuthOpen(true)}}>Регистрация</button></div>:<div className="account-panel"><p>Вы вошли как <strong>{authUser.email}</strong></p><button className="text-link" onClick={()=>void supabase?.auth.signOut()}>Выйти из аккаунта</button><h3>Мои записи</h3>{myBookings.length?myBookings.map(b=><div className="account-item" key={b.id}><b>{b.date} · {b.time}</b><span>{b.serviceIds.map(id=>state.services.find(x=>x.id===id)?.name||id).join(', ')}</span><small>Статус: {b.status}</small></div>):<p>Пока нет записей в этом аккаунте. Гостевые заявки не привязываются автоматически к профилю.</p>}<h3>Мои заказы</h3>{myOrders.length?myOrders.map(o=><div className="account-item" key={o.id}><b>Заказ #{o.id.slice(0,8)}</b><span>{money(o.total)}</span></div>):<p>Пока нет заказов.</p>}</div>}</Section>;
 const DetailsPage=()=>{const item=detail?.type==='service'?state.services.find(s=>s.id===detail.id):detail?.type==='product'?state.products.find(p=>p.id===detail.id):state.masters.find(m=>m.id===detail?.id);if(!detail||!item)return <Section eyebrow="ИНФОРМАЦИЯ" title="Не найдено"><button className="btn btn-outline" onClick={()=>go('Главная')}>{t("На главную")}</button></Section>;const isService=detail.type==='service',isProduct=detail.type==='product',asService=isService?item as Service:null,asProduct=isProduct?item as Product:null,asMaster=detail.type==='master'?item as Master:null;return <Section eyebrow={isService?'ПОДРОБНО ОБ УСЛУГЕ':isProduct?'ПОДРОБНО О ТОВАРЕ':'НАШ МАСТЕР'} title={itemText(item,'name',item.name)}><div className="detail-layout"><div className="detail-visual"><MediaImage src={item.image} alt={itemText(item,'name',item.name)}/></div><div className="detail-info"><div className="eyebrow">{asService?.category||asProduct?.category||asMaster?.specialty}</div><p className="lead">{asService?itemText(asService,'description',asService.description):asProduct?itemText(asProduct,'description',asProduct.description):asMaster?itemText(asMaster,'specialty',asMaster.specialty):t('Описание обновляется администратором.')}</p>{asService&&<><p><b>{t("Продолжительность:")}</b> {asService.duration}  {t("мин")}</p><h3>{t("Стоимость от")} {money(asService.price)}</h3><p className="hint">{t("Фактическая цена уточняется после консультации.")}</p><button className="btn btn-primary" onClick={()=>{setBookingServices([asService.id]);go('Запись')}}>{t("Записаться на услугу")} <ArrowUpRight size={17}/></button></>}{asProduct&&<><h3>{money(asProduct.price)}</h3>{asProduct.demo&&<p className="hint">{t("Демонстрационный товар: до коммерческого запуска заменить данные.")}</p>}<button className="btn btn-primary" onClick={()=>{setCart(v=>({...v,[asProduct.id]:(v[asProduct.id]||0)+1}));alert('Добавлено в корзину')}}>{t("В корзину")} <ShoppingCart size={17}/></button></>}{asMaster&&<><h3>{t("Услуги мастера")}</h3><div className="detail-services">{state.services.filter(s=>asMaster.serviceIds.includes(s.id)).map(s=><button key={s.id} onClick={()=>openDetail('service',s.id)}>{itemText(s,'name',s.name)} <ArrowUpRight size={15}/></button>)}</div><button className="btn btn-primary" onClick={()=>{setBookingMaster(asMaster.id);go('Запись')}}>{t("Записаться к мастеру")} <ArrowUpRight size={17}/></button></>}<button className="text-link" onClick={()=>go(isService?'Услуги':isProduct?'Магазин':'Мастера')}>{t("← Вернуться к списку")}</button></div></div></Section>};
 const CartPage=()=> <Section eyebrow="ВАШ ВЫБОР" title="Корзина и заказ"><div className="cart-layout"><div>{Object.entries(cart).length?Object.entries(cart).map(([id,qty])=>{const p=state.products.find(x=>x.id===id);if(!p)return null;return <div className="cart-row" key={id}><MediaImage src={p.image} alt={itemText(p,'name',p.name)}/><div><b>{itemText(p,'name',p.name)}</b><p>{money(p.price)}</p></div><div className="qty"><button onClick={()=>setCart(c=>({...c,[id]:Math.max(0,c[id]-1)}))}><Minus size={14}/></button>{qty}<button onClick={()=>setCart(c=>({...c,[id]:c[id]+1}))}><Plus size={14}/></button></div><button onClick={()=>setCart(c=>{const n={...c};delete n[id];return n})}><Trash2 size={17}/></button></div>}):<p className="lead">{t("Пока пусто. Выберите товары в магазине.")}</p>}</div><div className="checkout"><div className="eyebrow">{t("ОФОРМЛЕНИЕ")}</div><h3>{t("Итого:")} {money(cartTotal)}</h3><label className="field">{t("Имя")}<input value={orderName} onChange={e=>setOrderName(e.target.value)} placeholder="Ваше имя"/></label><label className="field">{t("Телефон")}<input value={orderPhone} onChange={e=>setOrderPhone(e.target.value)} placeholder="+996..."/></label><button className="btn btn-primary" onClick={()=>void submitOrder()}>{t("Оформить через WhatsApp")} <ArrowRight size={16}/></button>{telegramOwnerLink()&&<button className="btn btn-outline checkout-telegram" onClick={()=>void submitOrder('telegram')}>{t("Заказать через Telegram")} <MessageCircle size={16}/></button>}{telegramOwnerLink()&&<p className="checkout-contact-note">{t("Telegram открывает чат владельца. Сообщение необходимо отправить вручную.")}</p>}</div></div></Section>;
 const GalleryPage=()=> <Section eyebrow="ПОРТФОЛИО" title="Вдохновение в деталях"><p className="lead">{t("Демонстрационные фотографии для концепции сайта. Реальные работы добавляются владельцем.")}</p><div className="gallery-full">{mediaGallery.map((img,i)=><MediaImage src={img} key={img} alt={`Работа ${i+1}`} loading="lazy"/>)}</div></Section>;
 const AcademyPage=()=> <Section eyebrow="EL BEM ACADEMY" title={siteText('academyTitle')}><div className="academy-highlight"><MediaImage src={content.academyImage} alt="Обучение"/><div><p>{siteText('academyText')}</p><div className="chips"><span className="chip-static">{t("Практика")}</span><span className="chip-static">{t("Консультация")}</span><span className="chip-static">{t("Индивидуальный подход")}</span></div><button className="btn btn-primary" onClick={()=>wa('Здравствуйте! Хочу узнать об обучении в EL BEM.')}>{t("Узнать об обучении в WhatsApp")} <ArrowUpRight size={16}/></button></div></div></Section>;
 const AboutPage=()=> <Section eyebrow="О НАС" title={siteText('aboutTitle')}><div className="feature-grid about-page"><div><p className="lead">{siteText('aboutText')}</p><p>{siteText('address')||t('Узген, Кыргызстан')}{t(". В демоверсии используются примерные изображения и цены из предоставленного прайса; подробности необходимо уточнить перед визитом.")}</p><button className="btn btn-primary" onClick={()=>go('Запись')}>{t("Записаться")} <ArrowRight size={16}/></button></div><MediaImage src={mediaGallery[0]} alt="EL BEM"/></div></Section>;
 const ReviewsPage=()=> <Section eyebrow="ОТЗЫВЫ" title="Ваши слова важны"><div className="review-grid">{state.reviews.map(r=><div className="review-card" key={r.id}><div className="stars">★★★★★</div><p>“{r.text}”</p><b>{r.name}</b>{r.image?<MediaImage src={r.image} alt="Прикреплённый отзыв"/>:null}</div>)}</div><p className="hint">{t("Демонстрационные отзывы отмечаются отдельно. Публикации салона не выдаются за проверенные независимые оценки.")}</p></Section>;
 const ContactPage=()=> <Section eyebrow="КОНТАКТЫ" title="Будем рады вам"><div className="contact-cards"><div><MapPin/><h3>{siteText('address')||t('Узген · Кыргызстан')}</h3><p>{siteText('openingHours')||t('Часы работы уточняются')}</p>{salonMapLink()&&<a className="text-link address-link" href={salonMapLink()!} target="_blank" rel="noopener noreferrer">{t("Открыть на карте")} <ArrowUpRight size={16}/></a>}</div><div><Instagram/><h3>Instagram</h3><a href="https://www.instagram.com/ozgon.salon.el_bem/" target="_blank" rel="noreferrer">@ozgon.salon.el_bem <ArrowUpRight size={15}/></a><p>{t("Свяжитесь с нами для записи и консультации.")}</p><button className="btn btn-primary" onClick={()=>wa('Здравствуйте! У меня вопрос о салоне.')}>WhatsApp <ArrowRight size={15}/></button></div></div></Section>;
 const [edit,setEdit]=useState<Record<string,any>|null>(null);const [editTable,setEditTable]=useState<'services'|'masters'|'products'|'reviews'|null>(null);const [saving,setSaving]=useState(false);const [scheduleMaster,setScheduleMaster]=useState('');const [scheduleDate,setScheduleDate]=useState(today());const [scheduleTime,setScheduleTime]=useState('09:00');
 const openEdit=(table:'services'|'masters'|'products'|'reviews',v?:any)=>{setEditTable(table);setEdit(v||({id:uid(),name:'',image:'',category:'',price:0,duration:60,description:'',serviceIds:[],active:true,text:''}))};
 const [categoryEdit,setCategoryEdit]=useState<CatalogCategory|null>(null);
 const categorySave=async()=>{if(!categoryEdit)return;const value={...categoryEdit,name:categoryEdit.name.trim()};if(!value.name){alert('Укажите название категории');return}if(state.categories.some(c=>c.id!==value.id&&c.kind===value.kind&&c.name.toLowerCase()===value.name.toLowerCase())){alert('Такая категория уже существует');return}
 const old=state.categories.find(c=>c.id===value.id);const table=value.kind==='service'?'services':'products';const renamed=old&&old.name!==value.name?(state[table] as (Service|Product)[]).filter(item=>item.category===old.name):[];
 try{if(configured){const {error}=await supabase!.from('catalog_categories').upsert({id:value.id,name:value.name,kind:value.kind,image:value.image,active:value.active,sort_order:value.sortOrder,localized:value.localized||{}});if(error)throw error;for(const item of renamed){const {error:renameError}=await supabase!.from(table).update({category:value.name}).eq('id',item.id);if(renameError)throw renameError}};
 setState(prev=>({...prev,categories:[...prev.categories.filter(c=>c.id!==value.id),value],services:value.kind==='service'?prev.services.map(x=>x.category===old?.name?{...x,category:value.name}:x):prev.services,products:value.kind==='product'?prev.products.map(x=>x.category===old?.name?{...x,category:value.name}:x):prev.products}));setCategoryEdit(null);alert('Категория сохранена')}catch(e){alert('Ошибка сохранения категории: '+String(e))}};
 const categoryDelete=async(c:CatalogCategory)=>{if([...state.services,...state.products].some(x=>x.category===c.name)){alert('Категория используется. Сначала перенесите связанные товары или услуги.');return}if(!confirm('Удалить категорию?'))return;try{if(configured){const {error}=await supabase!.from('catalog_categories').delete().eq('id',c.id);if(error)throw error}setState(prev=>({...prev,categories:prev.categories.filter(x=>x.id!==c.id)}));alert('Категория удалена')}catch(e){alert(String(e))}};
 const [uploading,setUploading]=useState(false);
 const [weekday,setWeekday]=useState(1);const [opening,setOpening]=useState('09:00');const [closing,setClosing]=useState('19:00');const [working,setWorking]=useState(true);
 const [weeklyHours,setWeeklyHours]=useState<{master_id:string;weekday:number;open_at:string;close_at:string;is_open:boolean}[]>([]);
 const [currentAdminPassword,setCurrentAdminPassword]=useState('');const [newAdminPassword,setNewAdminPassword]=useState('');
 useEffect(()=>{if(!configured||!supabase||!adminAuth)return;void supabase.from('master_hours').select('*').then(({data})=>{if(data)setWeeklyHours(data as typeof weeklyHours)})},[adminAuth]);
 useEffect(()=>{const row=weeklyHours.find(x=>x.master_id===scheduleMaster&&x.weekday===weekday);setOpening((row?.open_at||'09:00').slice(0,5));setClosing((row?.close_at||'19:00').slice(0,5));setWorking(row?.is_open??true)},[scheduleMaster,weekday,weeklyHours]);
 const saveWeekly=async()=>{if(!scheduleMaster){alert('Сначала выберите мастера');return}if(closing<=opening){alert('Конец смены должен быть позже начала');return}const row={master_id:scheduleMaster,weekday,open_at:opening,close_at:closing,is_open:working};try{if(configured){const {error}=await supabase!.from('master_hours').upsert(row);if(error)throw error}setWeeklyHours(old=>[...old.filter(x=>!(x.master_id===scheduleMaster&&x.weekday===weekday)),row]);alert(configured?'График сохранён':'DEMO: график не сохраняется в общей базе')}catch(e){alert(String(e))}};
 const changeAdminPassword=async()=>{if(!configured||!supabase){alert('Подключите Supabase');return}if(newAdminPassword.length<12){alert('Новый пароль должен содержать не менее 12 символов');return}const {data:{user}}=await supabase.auth.getUser();if(!user?.email)return;const {error:loginError}=await supabase.auth.signInWithPassword({email:user.email,password:currentAdminPassword});if(loginError){alert('Текущий пароль не подходит');return}const {error}=await supabase.auth.updateUser({password:newAdminPassword});if(error){alert('Не удалось изменить пароль: '+error.message);return}setCurrentAdminPassword('');setNewAdminPassword('');alert('Пароль изменён')};
 const uploadImage=async(file:File,onSaved:(url:string)=>void)=>{
  if(!/^image\/(jpeg|png|webp|gif|avif)$/.test(file.type)){alert('Выберите JPEG, PNG, WebP, GIF или AVIF. HEIC сначала переведите в JPEG.');return}
  if(file.size>(configured?10:25)*1024*1024){alert(configured?'Максимум 10 МБ для Supabase Storage':'Максимум 25 МБ для локальной галереи');return}
  setUploading(true);
  try{
    if(configured){
      const path=`site/${uid()}-${file.name.replace(/[^a-zA-Z0-9._-]/g,'_')}`;
      const {error}=await supabase!.storage.from('site-media').upload(path,file,{contentType:file.type,upsert:false});
      if(error)throw error;
      onSaved(supabase!.storage.from('site-media').getPublicUrl(path).data.publicUrl);
    }else{
      // Stored across reloads on this device; media doesn't exhaust localStorage.
      onSaved(await saveLocalImage(file));
      alert('Фотография сохранена на этом устройстве. Для других устройств нужен Supabase Storage.');
    }
  }catch(e){alert('Не удалось загрузить изображение: '+String(e))}
  finally{setUploading(false)}
 };

 const uploadAudio=async(file:File,onSaved:(url:string)=>void)=>{const types=['audio/mpeg','audio/mp3','audio/wav','audio/x-wav','audio/ogg','audio/mp4','audio/x-m4a'];if(!types.includes(file.type)&&!/\.(mp3|wav|ogg|m4a)$/i.test(file.name)){alert('Допустимые форматы: MP3, WAV, OGG, M4A');return}if(file.size>20*1024*1024){alert('Для музыки установлен лимит 20 МБ');return}setUploading(true);try{if(configured){const path=`audio/${uid()}-${file.name.replace(/[^a-zA-Z0-9._-]/g,'_')}`;const {error}=await supabase!.storage.from('site-media').upload(path,file,{contentType:file.type||'audio/mpeg'});if(error)throw error;const {data}=supabase!.storage.from('site-media').getPublicUrl(path);onSaved(data.publicUrl)}else{onSaved(URL.createObjectURL(file));alert('DEMO: музыка работает только до перезагрузки. Для постоянного хранения подключите Supabase Storage')}}catch(e){alert('Не удалось загрузить аудио: '+String(e))}finally{setUploading(false)}};
 const saveEdit=async()=>{if(!edit||!editTable)return;setSaving(true);try{if(configured){const payload={...edit};if(editTable==='reviews')delete payload.active;await saveEntity(editTable,payload)}change(editTable,[...(state[editTable] as any[]).filter(x=>x.id!==edit.id),edit] as any);setEdit(null);alert('Сохранено')}catch(e){alert(String(e))}finally{setSaving(false)}};
 const remove=async(table:'services'|'masters'|'products'|'reviews',id:string)=>{if(!confirm('Удалить запись? Для коммерческой базы важна история связанных заказов.'))return;try{if(configured)await deleteEntity(table,id);change(table,(state[table] as any[]).filter(x=>x.id!==id) as any);alert('Удалено')}catch(e){alert(String(e))}};
 const updateBooking=async(b:Booking,status:Booking['status'])=>{try{if(configured)await saveEntity('bookings',{...b,status});change('bookings',state.bookings.map(x=>x.id===b.id?{...x,status}:x));alert('Статус обновлён')}catch(e){alert(String(e))}};
 const salonMapLink=()=>{try{const raw=(content.addressMapUrl||'').trim();if(!raw)return null;const url=new URL(raw);return ['https:','http:'].includes(url.protocol)?url.href:null}catch{return null}};
 const telegramOwnerLink=()=>{const raw=(content.telegramOwner||'').trim();const match=raw.match(/^(?:@|https?:\/\/(?:www\.)?t\.me\/)?([A-Za-z][A-Za-z0-9_]{4,31})\/?$/i);return match?`https://t.me/${match[1]}`:null};
 const bookingTelegramText=(b:Booking)=>`EL BEM — заявка #${b.id.slice(0,8)}\nКлиент: ${b.name}\nТелефон: ${b.phone}\nУслуги: ${b.serviceIds.map(id=>state.services.find(s=>s.id===id)?.name||id).join(', ')}\nМастер: ${state.masters.find(m=>m.id===b.masterId)?.name||'Любой свободный'}\nДата: ${b.date} ${b.time}\nСтатус: ${b.status}\nКомментарий: ${b.note||'—'}`;
 const sendTelegramManually=async(b:Booking)=>{const link=telegramOwnerLink();if(!link){alert('Сначала укажите @username владельца Telegram в Настройках и сохраните. Номер телефона не подходит.');setAdminPage('Настройки');return}try{await navigator.clipboard.writeText(bookingTelegramText(b));window.open(link,'_blank','noopener,noreferrer');alert('Заявка скопирована. В открывшемся Telegram вставьте текст и нажмите «Отправить». Автоматической отправки нет.')}catch{window.open(link,'_blank','noopener,noreferrer');alert('Telegram открыт. Скопируйте данные заявки вручную: браузер запретил доступ к буферу обмена.')}};
 const saveContent=async()=>{try{if(configured)await saveEntity('site_content',{id:1,data:content});alert('Настройки сохранены')}catch(e){alert(String(e))}};
 const addBlock=async()=>{const slot=scheduleMaster?`${scheduleMaster}|${scheduleDate}|${scheduleTime}`:`${scheduleDate}|${scheduleTime}`;if(state.blocked.includes(slot))return;try{if(configured)await saveEntity('blocked_slots',{slot});change('blocked',[...state.blocked,slot]);alert('Интервал закрыт')}catch(e){alert(String(e))}};
 const Admin=()=> <div className="admin-shell"><aside className="admin-side"><div className="admin-brand">✦ EL BEM <small>CONTROL PANEL</small></div>{AdminNav.map(p=><button key={p} className={adminPage===p?'selected':''} onClick={()=>{setAdminPage(p);setEdit(null)}}>{p==='Обзор'?<LayoutDashboard size={17}/>:p==='Записи'?<CalendarDays size={17}/>:p==='Расписание'?<Clock size={17}/>:p==='Услуги'?<Scissors size={17}/>:p==='Мастера'?<Users size={17}/>:p==='Товары'?<Package size={17}/>:p==='Категории'?<Tag size={17}/>:p==='Контент сайта'?<Image size={17}/>:p==='Отзывы'?<Star size={17}/>:<Settings size={17}/>}<span>{p}</span></button>)}<button onClick={()=>{setAdmin(false);go('Главная')}}><ArrowLeft size={17}/>  {t("Вернуться на сайт")}</button><button onClick={async()=>{await supabase?.auth.signOut();setAdminAuth(false);alert('Вы вышли')}}><LogOut size={17}/>  {t("Выйти")}</button></aside><div className="admin-content"><div className="admin-top"><div><div className="eyebrow">{t("ПАНЕЛЬ ВЛАДЕЛЬЦА")}</div><h1>{adminPage}</h1></div><span className="status-pill">{configured?'Supabase':'Локальный деморежим'}</span></div>{adminPage==='Обзор'?<><div className="stat-grid">{[['Новые заявки',state.bookings.filter(b=>b.status==='pending').length],['Услуги',state.services.length],['Мастера',state.masters.length],['Товары',state.products.length]].map(([label,n])=><div className="stat" key={String(label)}><span>{label}</span><strong>{n}</strong></div>)}</div><div className="admin-panel"><h3>{t("Быстрые действия")}</h3><div className="admin-actions">{['Записи','Расписание','Услуги','Мастера','Контент сайта'].map(p=><button key={p} onClick={()=>setAdminPage(p)}>{p}<ArrowUpRight size={15}/></button>)}</div><p className="hint">{t("Важно: деморежим хранит данные только в этом браузере. Для реальных клиентов необходимо защищённое подключение Supabase.")}</p></div></>:null}
 {adminPage==='Записи'?<div className="admin-panel"><h3>{t("Заявки клиентов")}</h3><div className="table-scroll"><table><thead><tr><th>{t("Клиент")}</th><th>{t("Услуги")}</th><th>{t("Дата и время")}</th><th>{t("Статус")}</th><th>{t("Действия")}</th></tr></thead><tbody>{state.bookings.map(b=><tr key={b.id}><td>{b.name}<small>{b.phone}</small></td><td>{b.serviceIds.map(id=>state.services.find(s=>s.id===id)?.name).join(', ')}</td><td>{b.date} · {b.time}</td><td><span className="status-pill">{b.status}</span></td><td><button className="mini-btn" onClick={()=>updateBooking(b,'confirmed')}>{t("Подтвердить")}</button> <button className="mini-btn" onClick={()=>updateBooking(b,'cancelled')}>{t("Отменить")}</button> <button type="button" className="mini-btn" title="Скопировать заявку и открыть Telegram владельца" onClick={()=>void sendTelegramManually(b)}>Telegram ↗</button></td></tr>)}</tbody></table>{!state.bookings.length?<p className="hint">{t("Заявок пока нет")}</p>:null}</div></div>:null}
 {adminPage==='Расписание'?<div className="admin-panel"><h3>{t("Доступное время")}</h3><p className="muted">{t("В деморежиме можно закрывать отдельные интервалы. Для настоящего салона необходим полноценный серверный график по мастерам.")}</p><div className="form-grid"><label className="field">{t("Мастер")}<select value={scheduleMaster} onChange={e=>setScheduleMaster(e.target.value)}><option value="">{t("Все мастера · демо")}</option>{state.masters.map(m=><option value={m.id} key={m.id}>{itemText(m,'name',m.name)}</option>)}</select></label><label className="field">{t("Дата")}<input type="date" value={scheduleDate} onChange={e=>setScheduleDate(e.target.value)}/></label><label className="field">{t("Время")}<select value={scheduleTime} onChange={e=>setScheduleTime(e.target.value)}>{times.map(t=><option key={t}>{t}</option>)}</select></label><button className="btn btn-primary" onClick={addBlock}>{t("Закрыть интервал")} <Plus size={16}/></button></div><div className="schedule-weekly"><h4>Рабочие часы мастера</h4><p className="hint">Выберите мастера выше, затем день недели, начало и конец смены. Изменения сохраняются в Supabase.</p><div className="form-grid"><label className="field">День недели<select value={weekday} onChange={e=>setWeekday(Number(e.target.value))}>{['Воскресенье','Понедельник','Вторник','Среда','Четверг','Пятница','Суббота'].map((day,i)=><option value={i} key={day}>{day}</option>)}</select></label><label className="field">Начало смены<input type="time" value={opening} onChange={e=>setOpening(e.target.value)}/></label><label className="field">Конец смены<input type="time" value={closing} onChange={e=>setClosing(e.target.value)}/></label><label className="switch-row"><input type="checkbox" checked={working} onChange={e=>setWorking(e.target.checked)}/>Рабочий день</label></div><button className="btn btn-primary" onClick={saveWeekly}>Сохранить график <Save size={16}/></button></div><h4>Закрытые интервалы</h4><div className="chips">{state.blocked.map(slot=><button key={slot} onClick={async()=>{try{if(configured){const {error}=await supabase!.from('blocked_slots').delete().eq('slot',slot);if(error)throw error}change('blocked',state.blocked.filter(x=>x!==slot))}catch(e){alert(String(e))}}}>{slot} <X size={13}/></button>)}</div></div>:null}
 {(['Услуги','Мастера','Товары','Отзывы'].includes(adminPage))?<div className="admin-panel"><div className="row-between"><h3>{adminPage}</h3><button className="btn btn-primary small-btn" onClick={()=>openEdit(adminPage==='Услуги'?'services':adminPage==='Мастера'?'masters':adminPage==='Товары'?'products':'reviews')}>{t("Добавить")} <Plus size={16}/></button></div><div className="admin-list">{(adminPage==='Услуги'?state.services:adminPage==='Мастера'?state.masters:adminPage==='Товары'?state.products:state.reviews).map((v:any)=><div className="admin-list-row" key={v.id}><MediaImage src={v.image||'https://placehold.co/80x80/eadfdc/633f51?text=EL+BEM'} alt=""/><div className="admin-list-info"><b>{v.name||v.text?.slice(0,50)}</b><span>{v.category||v.specialty||v.description||'Отзыв'} {typeof v.price==='number'?` · ${money(v.price)}`:''}</span></div><button onClick={()=>openEdit(adminPage==='Услуги'?'services':adminPage==='Мастера'?'masters':adminPage==='Товары'?'products':'reviews',v)} aria-label="Изменить"><PenLine size={17}/></button><button onClick={()=>remove(adminPage==='Услуги'?'services':adminPage==='Мастера'?'masters':adminPage==='Товары'?'products':'reviews',v.id)} aria-label="Удалить"><Trash2 size={17}/></button></div>)}</div></div>:null}
   {adminPage==='Категории'?<div className="admin-panel"><div className="row-between"><h3>Категории услуг и магазина</h3><button className="btn btn-primary small-btn" onClick={()=>setCategoryEdit({id:uid(),name:'',kind:'service',image:'',active:true,sortOrder:state.categories.length})}>Добавить категорию <Plus size={16}/></button></div><p className="hint">Категории связываются с услугами и товарами по названию. Изменённые названия обновляются в связанных элементах.</p><div className="admin-list">{state.categories.slice().sort((a,b)=>a.sortOrder-b.sortOrder).map(c=><div className="admin-list-row" key={c.id}><MediaImage src={c.image||'https://placehold.co/80x80/eadfdc/633f51?text=EL+BEM'} alt=""/><div className="admin-list-info"><b>{c.name}</b><span>{c.kind==='service'?'Услуги':'Магазин'} · {c.active?'Опубликована':'Скрыта'}</span></div><button aria-label="Изменить категорию" onClick={()=>setCategoryEdit(c)}><PenLine size={17}/></button><button aria-label="Удалить категорию" onClick={()=>void categoryDelete(c)}><Trash2 size={17}/></button></div>)}</div></div>:null}
{adminPage==='Контент сайта'?<div className="admin-panel"><h3>{t("Изображения и тексты")}</h3><p className="muted">{t("В демо-режиме фотографии с устройства сохраняются в этом браузере. После подключения Supabase они будут доступны на всех устройствах через Storage.")}</p><div className="admin-fields"><div className="admin-locale-picker"><b>Язык редактирования текстов</b><div className="chips">{(['ru','ky','en'] as const).map(l=><button type="button" key={l} className={editLocale===l?'selected':''} onClick={()=>setEditLocale(l)}>{l.toUpperCase()}</button>)}</div><small>RU — основной текст; KG и EN — независимые переводы. Незаполненные поля показывают русский вариант.</small></div>{([['heroTitle','Первый заголовок'],['heroEmphasis','Выделенный заголовок'],['heroSubtitle','Описание на главной'],['heroImage','Фото первого экрана (URL)'],['aboutTitle','Заголовок «О нас»'],['aboutText','Описание салона'],['academyTitle','Заголовок обучения'],['academyText','Текст обучения'],['academyImage','Фото обучения (URL)']] as const).map(([k,label])=><label className="field" key={k}>{label}{k.toLowerCase().includes('text')||k.toLowerCase().includes('subtitle')?<textarea rows={3} value={editLocale==='ru'?content[k]:(content.localized?.[editLocale]?.[k]||'')} onChange={e=>editLocale==='ru'?change('content',{...content,[k]:e.target.value}):change('content',{...content,localized:{...content.localized,[editLocale]:{...(content.localized?.[editLocale]||{}),[k]:e.target.value}}})}/>:k.toLowerCase().includes('image')?<ImageUpload library={mediaGallery} uploadImage={uploadImage} uploading={uploading} label={label} value={content[k]} onChange={v=>change('content',{...content,[k]:v})}/>:<input value={editLocale==='ru'?content[k]:(content.localized?.[editLocale]?.[k]||'')} onChange={e=>editLocale==='ru'?change('content',{...content,[k]:e.target.value}):change('content',{...content,localized:{...content.localized,[editLocale]:{...(content.localized?.[editLocale]||{}),[k]:e.target.value}}})}/>}</label>)}<div className="admin-gallery-editor"><h4>{t("Фотографии галереи")}</h4><p className="hint">{t("Загрузите новые фотографии или удалите старые. Публичная галерея обновится после сохранения настроек.")}</p><label className="field">{t("Добавить фотографии с устройства")}<input type="file" accept="image/jpeg,image/png,image/webp,image/gif,image/avif" multiple disabled={uploading} onChange={async e=>{const files=Array.from(e.target.files||[]);for(const f of files){await uploadImage(f,url=>setState(prev=>({...prev,content:{...prev.content,galleryImages:[...(prev.content.galleryImages??gallery),url]}})))}e.target.value=''}}/></label><div className="admin-gallery-grid">{mediaGallery.map((url,i)=><div className="admin-gallery-thumb" key={url+i}><MediaImage src={url} alt={`Фото галереи ${i+1}`}/><button type="button" onClick={()=>change('content',{...state.content,galleryImages:mediaGallery.filter((_,j)=>j!==i)})}>{t("Убрать")} <X size={13}/></button></div>)}</div></div><button className="btn btn-primary" onClick={saveContent}>{t("Сохранить изменения")} <Save size={17}/></button></div></div>:null}
 {adminPage==='Настройки'?<div className="admin-panel"><h3>{t("Настройки сайта")}</h3><div className="admin-fields"><div className="admin-locale-picker"><b>Язык адреса и графика</b><div className="chips">{(['ru','ky','en'] as const).map(l=><button type="button" key={l} className={editLocale===l?'selected':''} onClick={()=>setEditLocale(l)}>{l.toUpperCase()}</button>)}</div></div><label className="field">{t("WhatsApp (международный номер, только цифры)")}<input value={content.whatsapp} placeholder="996..." onChange={e=>change('content',{...content,whatsapp:e.target.value})}/></label><div className="telegram-admin-setting"><h4>Telegram владельца (без бота)</h4><p className="hint">Укажите публичный @username или ссылку https://t.me/username. Номер телефона не обеспечивает автоматическую отправку. В разделе «Записи» кнопка Telegram копирует заявку и открывает этот чат; отправить сообщение нужно вручную.</p><label className="field">Telegram @username или ссылка<input value={content.telegramOwner||''} placeholder="@username или https://t.me/username" onChange={e=>change('content',{...content,telegramOwner:e.target.value})}/></label><div className="telegram-settings-actions"><button type="button" className="btn btn-outline" onClick={()=>change('content',{...content,telegramOwner:''})}>Удалить Telegram</button>{telegramOwnerLink()?<a className="btn btn-outline" href={telegramOwnerLink()||'#'} target="_blank" rel="noopener noreferrer">Проверить ссылку ↗</a>:<span className="hint">Пока нет корректного адреса Telegram</span>}</div><p className="hint">После изменения нажмите «Сохранить настройки» ниже.</p></div><label className="field">{t("Адрес салона")}<input value={editLocale==='ru'?(content.address||''):(content.localized?.[editLocale]?.address||'')} onChange={e=>editLocale==='ru'?change('content',{...content,address:e.target.value}):change('content',{...content,localized:{...content.localized,[editLocale]:{...(content.localized?.[editLocale]||{}),address:e.target.value}}})}/></label><label className="field">{t("Ссылка на карту (Google Maps, 2GIS и др.)")}<input type="url" value={content.addressMapUrl||''} placeholder="https://maps.google.com/..." onChange={e=>change('content',{...content,addressMapUrl:e.target.value})}/></label>{content.addressMapUrl&&!salonMapLink()&&<p className="error">Укажите полную ссылку http:// или https://</p>}<label className="field">{t("График работы салона")}<input value={editLocale==='ru'?(content.openingHours||''):(content.localized?.[editLocale]?.openingHours||'')} onChange={e=>editLocale==='ru'?change('content',{...content,openingHours:e.target.value}):change('content',{...content,localized:{...content.localized,[editLocale]:{...(content.localized?.[editLocale]||{}),openingHours:e.target.value}}})}/></label><label className="field">{t("Ссылка на аудиофайл HTTPS")}<input value={content.musicUrl} placeholder="https://...mp3" onChange={e=>change('content',{...content,musicUrl:e.target.value})}/></label><label className="field">{t("Или загрузите музыку с устройства (MP3, WAV, OGG, M4A)")}<input type="file" accept="audio/mpeg,audio/mp3,audio/wav,audio/ogg,audio/mp4,audio/x-m4a,.mp3,.wav,.ogg,.m4a" disabled={uploading} onChange={e=>{const file=e.target.files?.[0];if(file)void uploadAudio(file,url=>change('content',{...content,musicUrl:url}));e.target.value=''}}/></label><label className="switch-row"><input type="checkbox" checked={content.musicEnabled} onChange={e=>change('content',{...content,musicEnabled:e.target.checked})}/>  {t("Включить возможность фоновой музыки")}</label><label className="switch-row"><input type="checkbox" checked={content.shopEnabled} onChange={e=>change('content',{...content,shopEnabled:e.target.checked})}/>  {t("Магазин доступен посетителям")}</label><button className="btn btn-primary" onClick={saveContent}>{t("Сохранить настройки")} <Save size={17}/></button>{configured?<button className="text-link" onClick={async()=>{const email=prompt('Подтверждённый email администратора для сброса пароля');if(!email)return;const {error}=await supabase!.auth.resetPasswordForEmail(email,{redirectTo:window.location.origin});alert(error?error.message:'Проверьте почту для дальнейшей смены пароля')}}>{t("Сбросить пароль по email")} <ArrowUpRight size={15}/></button>:<p className="hint">Защищённый вход и смена пароля требуют настройки Supabase.</p>}{configured&&<div className="password-box"><h4>Изменить пароль администратора</h4><label className="field">Текущий пароль<input type="password" autoComplete="current-password" value={currentAdminPassword} onChange={e=>setCurrentAdminPassword(e.target.value)}/></label><label className="field">Новый пароль (от 12 символов)<input type="password" autoComplete="new-password" value={newAdminPassword} onChange={e=>setNewAdminPassword(e.target.value)}/></label><button className="btn btn-outline" onClick={changeAdminPassword}>Изменить пароль</button></div>}</div></div>:null}
   </div>{categoryEdit&&<div className="modal-backdrop"><div className="modal edit-modal"><button className="modal-close" onClick={()=>setCategoryEdit(null)}><X/></button><h2>Категория</h2><div className="admin-locale-picker"><b>Язык названия</b><div className="chips">{(['ru','ky','en'] as const).map(l=><button type="button" key={l} className={editLocale===l?'selected':''} onClick={()=>setEditLocale(l)}>{l.toUpperCase()}</button>)}</div></div><label className="field">Название<input value={editLocale==='ru'?categoryEdit.name:categoryEdit.localized?.[editLocale]?.name||''} onChange={e=>setCategoryEdit(v=>v&&(editLocale==='ru'?{...v,name:e.target.value}:{...v,localized:{...v.localized,[editLocale]:{...v.localized?.[editLocale],name:e.target.value}}}))}/></label><label className="field">Раздел<select value={categoryEdit.kind} onChange={e=>setCategoryEdit(v=>v&&({...v,kind:e.target.value as 'service'|'product'}))}><option value="service">Услуги</option><option value="product">Магазин</option></select></label><ImageUpload library={mediaGallery} uploadImage={uploadImage} uploading={uploading} label="Обложка категории" value={categoryEdit.image} onChange={image=>setCategoryEdit(v=>v&&({...v,image}))}/><label className="field">Порядок<input type="number" value={categoryEdit.sortOrder} onChange={e=>setCategoryEdit(v=>v&&({...v,sortOrder:Number(e.target.value)}))}/></label><label className="switch-row"><input type="checkbox" checked={categoryEdit.active} onChange={e=>setCategoryEdit(v=>v&&({...v,active:e.target.checked}))}/>Опубликована</label><button className="btn btn-primary" onClick={()=>void categorySave()}>Сохранить категорию</button></div></div>}{edit&&editTable&&<div className="modal-backdrop"><div className="modal edit-modal"><button className="modal-close" onClick={()=>setEdit(null)}><X/></button><h2>{edit.name?'Редактировать':'Новая запись'}</h2><div className="admin-fields"><div className="admin-locale-picker"><b>Язык описаний</b><div className="chips">{(['ru','ky','en'] as const).map(l=><button type="button" key={l} className={editLocale===l?'selected':''} onClick={()=>setEditLocale(l)}>{l.toUpperCase()}</button>)}</div><small>Переводятся название, описание и специализация. Остальные поля общие.</small></div>{(editTable==='reviews'?[['name','Автор'],['text','Текст'],['image','Ссылка на фото']]:editTable==='masters'?[['name','Имя'],['specialty','Специализация'],['image','Фото (URL)'],['serviceIds','ID услуг через запятую']]:[['name','Название'],['category','Категория'],['description','Описание'],['image','Фото (URL)'],['price','Цена'],...(editTable==='services'?[['duration','Длительность в минутах']]:[])]).map(([k,label])=><label className="field" key={k}>{label}{k==='category'?<select value={edit[k]||''} onChange={e=>setEdit(v=>({...v,category:e.target.value}))}><option value="">Выберите категорию</option>{state.categories.filter(c=>c.kind===(editTable==='products'?'product':'service')&&c.active).map(c=><option key={c.id} value={c.name}>{c.name}</option>)}{edit[k]&&!state.categories.some(c=>c.name===edit[k])?<option value={edit[k]}>{edit[k]}</option>:null}</select>:k==='image'?<ImageUpload library={mediaGallery} uploadImage={uploadImage} uploading={uploading} label="Фотография" value={String(edit[k]||'')} onChange={url=>setEdit(v=>({...v,image:url}))}/>:<input value={editLocale!=='ru'&&['name','description','specialty','text'].includes(k)?String(edit.localized?.[editLocale]?.[k]??''):Array.isArray(edit[k])?edit[k].join(', '):String(edit[k]??'')} onChange={e=>setEdit(v=>v?(editLocale!=='ru'&&['name','description','specialty','text'].includes(k)?({...v,localized:{...v.localized,[editLocale]:{...v.localized?.[editLocale],[k]:e.target.value}}}):({...v,[k]:k==='price'||k==='duration'?Number(e.target.value):k==='serviceIds'?e.target.value.split(',').map(x=>x.trim()).filter(Boolean):e.target.value})):null)}/>}</label>)}<label className="switch-row"><input type="checkbox" checked={edit.active!==false} onChange={e=>setEdit(v=>({...v,active:e.target.checked}))}/>  {t("Опубликовано")}</label><button className="btn btn-primary" disabled={saving} onClick={saveEdit}>{saving?'Сохранение…':'Сохранить'}</button></div></div></div>}</div>;
 const AdminGate=()=> <div className="auth-gate"><div className="auth-card"><ShieldCheck size={31}/><h2>{t("Вход владельца")}</h2><p>{t("Защищённая панель EL BEM. Для реального входа сначала настройте Supabase и роль администратора.")}</p>{!configured?<><div className="demo-notice">{t("DEMO: здесь можно осмотреть дизайн админки и протестировать локальные изменения. Данные не защищены и не передаются между устройствами.")}</div><button className="btn btn-primary" onClick={()=>setAdminAuth(true)}>{t("Посмотреть демо-панель")} <ArrowRight size={17}/></button></>:<><label className="field">Email<input type="email" value={authEmail} onChange={e=>setAuthEmail(e.target.value)} /></label><label className="field">{t("Пароль")}<input type="password" value={authPass} onChange={e=>setAuthPass(e.target.value)}/></label><button className="btn btn-primary" onClick={login}>{t("Войти в админку")} <ArrowRight size={17}/></button>{authError&&<p className="error">{authError}</p>}</>}<button className="text-link" onClick={()=>go('Главная')}>{t("← Вернуться на сайт")}</button></div></div>;
 const Footer=()=> <footer className="footer"><div className="shell footer-grid"><div><div className="footer-logo">✦ EL BEM</div><p>{t("Красота в каждой детали.")}<br/>{t("Узген, Кыргызстан.")}</p></div><div><b>{t("Исследуйте")}</b>{['Услуги','Мастера','Запись','Обучение'].map(p=><button key={p} onClick={()=>go(p)}>{p}</button>)}</div><div><b>{t("Информация")}</b>{['О нас','Галерея','Контакты','Отзывы'].map(p=><button key={p} onClick={()=>go(p)}>{p}</button>)}</div><div><b>{t("Связь")}</b><a href="https://www.instagram.com/ozgon.salon.el_bem/" target="_blank" rel="noreferrer">Instagram ↗</a><button onClick={()=>wa('Здравствуйте!')}>WhatsApp ↗</button><button className="admin-footer-link" onClick={openAdmin}>{t("Для администратора")} <Lock size={12}/></button></div></div><div className="shell footer-bottom"><span>{t("© EL BEM BEAUTY · Демонстрационный проект")}</span><span>{t("Фотографии и часть данных — иллюстративные")}</span></div></footer>;
 return <>{!admin&&BackgroundDecor()}{Header()}{connectedError&&<div className="error-banner">{t("Ошибка Supabase:")} {connectedError}{t(". Проверьте настройки. Реальные операции могут быть недоступны.")}</div>}{loading?<main className="loading">{t("Подключение данных…")}</main>:admin?(adminAuth?Admin():AdminGate()):<main key={page}>{page==='Главная'?Home():page==='Подробнее'?DetailsPage():page==='Услуги'?ServicesPage():page==='Мастера'?MastersPage():page==='Запись'?BookingPage():page==='Обучение'?AcademyPage():page==='Магазин'?ShopPage():page==='Корзина'?CartPage():page==='Галерея'?GalleryPage():page==='Отзывы'?ReviewsPage():page==='О нас'?AboutPage():page==='Контакты'?ContactPage():page==='Кабинет'?AccountPage():Home()}</main>}{!admin&&Footer()}{!admin&&Floating()}{notification&&<div className="toast">{notification}<button onClick={()=>setNotification('')}><X size={13}/></button></div>}{authOpen&&<div className="modal-backdrop"><div className="modal"><button className="modal-close" onClick={()=>setAuthOpen(false)}><X/></button><h2>{authMode==='signup'?'Регистрация':'Войти'}</h2><p>{t("Необязательный личный кабинет для экзамена")}</p><label className="field">Email<input value={authEmail} onChange={e=>setAuthEmail(e.target.value)}/></label><label className="field">{t("Пароль")}<input type="password" value={authPass} onChange={e=>setAuthPass(e.target.value)}/></label>{authError&&<div className="error">{authError}</div>}<button className="btn btn-primary" onClick={login}>{authMode==='signup'?'Зарегистрироваться':'Войти'}</button><button className="text-link" onClick={()=>setAuthMode(authMode==='signup'?'login':'signup')}>{authMode==='signup'?'Уже есть аккаунт?':'Создать аккаунт'}</button></div></div>}</>;
}
